import {createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {isJsonObject} from '@letsduck/domain';
export interface FrozenResult {status:number;stdout:string;stderr:string;error?:Error;entries:ReadonlyMap<string,Buffer>}
/** Historical Python output, matched to exact synthetic input; never regenerated by the implementation under test. */
export function frozenOracle(name:string,input:string):FrozenResult {
 const data:unknown=JSON.parse(readFileSync(new URL('../oracles/'+name+'.json',import.meta.url),'utf8'));
 if(!isJsonObject(data)||data.schema!=='letsduck-frozen-oracle/1'||data.referenceCommit!=='d5c38e4fa890a4eca40d8857317ac463163b46c3'||data.capturedExitCode!==0||!Array.isArray(data.cases))throw new Error('Invalid historical oracle: '+name);
 const digest=createHash('sha256').update(input).digest('hex'),item=data.cases.find(value=>isJsonObject(value)&&value.inputSha256===digest);
 if(!isJsonObject(item)||typeof item.output!=='string')throw new Error('No historical oracle for '+name+' input '+digest+'; capture the approved historical source explicitly');
 const entries=new Map<string,Buffer>();if(isJsonObject(item.entries))for(const[key,value]of Object.entries(item.entries)){if(typeof value!=='string')throw new TypeError('Invalid oracle entry');entries.set(key,Buffer.from(value,'base64'));}
 return {status:0,stdout:item.output,stderr:'',entries};
}
